   using Experimental::digits_v;
   constexpr auto dig = digits_v<T>;
   int const rem      = s % dig;
@@ -414,10 +392,8 @@ rotl(T x, int s) noexcept {
   return (x >> -rem) | (x << ((dig + rem) % dig));  // rotr(x, -rem)
